/*
 * Demo of the DrawingManager on a daily SPY chart (demo/public): a
 * TradingView-style left toolbar with the tools under TradingView's groups
 * (demo/tool-groups.ts, generated by docs/tools_md.py), magnet, keep
 * drawing, hide all, remove all, a selection bar (Anchor drawing, hide,
 * delete), an inline text / table cell editor and JSON export / import as
 * files.
 * `window.dm` / `window.chart` / `window.series` / `window.lwcd` (the library
 * module) for scripted checks; `window.autoText` answers the text editor
 * request without the editor.
 */
import { cacheImage, decodeImage, isAnchorable, type DrawingManager, type Drawing, type DrawingKind, type MagnetMode } from "lightweight-charts-drawing";
import { ICONS } from "./icons";
import { TOOL_COUNT, TOOL_GROUPS, type ToolEntry } from "./tool-groups";
import css from "./demo.css?raw";
import html from "./index.html?raw";
const el = <K extends keyof HTMLElementTagNameMap>(tag: K, cls?: string, html?: string) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
};

/** Tool entry per kind (title, placement) from the TradingView groups. */
const TOOLS = new Map<string, ToolEntry & { group: string }>();
for (const g of TOOL_GROUPS) for (const s of g.sections) for (const t of s.tools) TOOLS.set(t.kind, { ...t, group: g.title });
TOOLS.set("font-icon", { kind: "font-icon", title: "Emoji", placement: "1 click", group: "emoji" });

/** A few Unicode emojis for the font-icon tool (TradingView Icons group). */
const EMOJIS = ["🚀", "📈", "📉", "💰", "💵", "🔥", "⚡", "🎯", "✅", "❌", "⚠️", "⭐", "🔔", "⏰", "💡", "📌",
  "🐂", "🐻", "🐳", "🦄", "👍", "👎", "👀", "💎", "😀", "😎", "🤔", "😱", "🤯", "🥳", "😭", "🙏"];


/** Upstream demo UI, mechanically adapted to an existing manager and scoped DOM.
 * See README.md and demo.ts.txt for the unchanged source and provenance. */
export function mountUpstreamDrawingUI(host: HTMLElement, dm: DrawingManager, options: { chartContainer?:HTMLElement; assetScope: string; saveImage: (name:string,file:Blob)=>Promise<void>; onEditorChange:(open:boolean)=>void; isEditable:()=>boolean }) {
 const root = host.shadowRoot ?? host.attachShadow({mode:"open"});
 const parsed = new DOMParser().parseFromString(html, "text/html");
 const style = document.createElement("style");
 style.textContent = css.replace(":root", ":host") + `
 :host { font:13px var(--font);color:var(--text);display:flex;flex-direction:column;pointer-events:none; }
 #rail,#flyout,#selbar,#editor { pointer-events:auto; }
 #rail,#status { background:var(--bg); }
 #hint { min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis; }
 #count { flex:none; }
 #main { min-height:0; }
 #chartWrap { pointer-events:none; }
 #status { flex:none;overflow:hidden;white-space:nowrap; }
 [hidden] { display:none !important; }
 `;
 root.replaceChildren(style,...Array.from(parsed.body.children).filter(e=>e.tagName!=="SCRIPT"));
 const $ = <T extends HTMLElement>(id:string) => root.getElementById(id) as T;
 const cleanup:Array<()=>void> = [];
 if(options.chartContainer){
  const wrap=$('chartWrap'),target=options.chartContainer;
  const align=()=>{
   const parent=$('main').getBoundingClientRect(),bounds=target.getBoundingClientRect();
   Object.assign(wrap.style,{position:'absolute',left:`${bounds.left-parent.left}px`,top:`${bounds.top-parent.top}px`,width:`${bounds.width}px`,height:`${bounds.height}px`});
  };
  align();
  if(typeof ResizeObserver!=='undefined'){
   const observer=new ResizeObserver(align);observer.observe(target);observer.observe(host);
   cleanup.push(()=>observer.disconnect());
  }
 }
 let disposed=false;
 const timers=new Set<ReturnType<typeof setTimeout>>();
 const later=(fn:()=>void,ms=0)=>{const timer=setTimeout(()=>{timers.delete(timer);if(!disposed)fn();},ms);timers.add(timer);return timer;};
 const listen=<K extends keyof WindowEventMap>(target:EventTarget,type:K,fn:(e:WindowEventMap[K])=>void,options?:boolean|AddEventListenerOptions)=>{
  target.addEventListener(type,fn as EventListener,options);cleanup.push(()=>target.removeEventListener(type,fn as EventListener,options));
 };
 const subscribe = dm.on.bind(dm) as (event:string,fn:(...args:never[])=>void)=>()=>void;
 const watch = ((event:string,fn:(...args:never[])=>void)=>{const off=subscribe(event,fn);cleanup.push(off);return off;}) as DrawingManager["on"];

  // ---- status line
  let note = "";
  let noteTimer = 0;
  const hint = $("hint");
  const flash = (s: string) => {
    note = s;
    clearTimeout(noteTimer);
    noteTimer = later(() => { note = ""; refreshHint(); }, 3000);
    refreshHint();
  };
  const refreshHint = () => {
    if (note) { hint.innerHTML = note; return; }
    const k = dm.tool();
    const t = k ? TOOLS.get(k) : undefined;
    if (t) hint.innerHTML = `<b>${t.title}</b>: ${t.placement} on the chart. <kbd>Esc</kbd> cancels. <kbd>Shift</kbd> keeps 45° steps.`;
    else if (dm.selection().length) hint.innerHTML = `Drag the points or the body to edit. <kbd>Ctrl</kbd> + drag clones, <kbd>Del</kbd> removes, <kbd>Esc</kbd> deselects.`;
    else hint.innerHTML = `Pick a tool in the left toolbar, then click on the chart. Click a drawing to select it.`;
  };
  const refreshCount = () => {
    const n = dm.drawings().length;
    $("count").textContent = `${n} drawing${n === 1 ? "" : "s"} · ${TOOL_COUNT} tools`;
  };
  watch("change", refreshCount);
  refreshCount();

  // ---- flyout menus
  const flyout = $("flyout");
  let openBtn: HTMLElement | null = null;
  const closeFlyout = () => {
    flyout.hidden = true;
    openBtn?.classList.remove("open");
    openBtn = null;
  };
  const openFlyout = (btn: HTMLElement, fill: (f: HTMLElement) => void) => {
    if (openBtn === btn) return closeFlyout();
    closeFlyout();
    flyout.replaceChildren();
    fill(flyout);
    flyout.hidden = false;
    openBtn = btn;
    btn.classList.add("open");
    const main = $("main").getBoundingClientRect();
    const b = btn.getBoundingClientRect();
    flyout.style.left = `${b.right - main.left + 6}px`;
    const top = Math.max(6, Math.min(b.top - main.top, main.height - flyout.offsetHeight - 6));
    flyout.style.top = `${top}px`;
  };
  listen(document, "pointerdown", (e) => {
    if (flyout.hidden) return;
    const t = e.target as Node;
    if (!flyout.contains(t) && !openBtn?.contains(t)) closeFlyout();
  });
  listen(document, "keydown", (e) => { if (e.key === "Escape") closeFlyout(); });
  const item = (label: string, hintText: string, onClick: () => void, active = false) => {
    const b = el("button", `fly-item${active ? " active" : ""}`);
    b.append(el("span", "", label));
    if (hintText) b.append(el("span", "hint", hintText));
    b.onclick = () => { closeFlyout(); onClick(); };
    return b;
  };

  // ---- left toolbar
  const rail = $("rail");
  const railBtn = (icon: string, title: string, more = false) => {
    const b = el("button", "tool", icon);
    b.title = title;
    if (more) b.append(el("span", "more"));
    rail.append(b);
    return b;
  };
  const sep = () => rail.append(el("div", "rail-sep"));

  const imageFile = $<HTMLInputElement>("imageFile");
  const arm = (kind: string) => {
    if (kind === "image") { imageFile.click(); return; }
    dm.setTool(kind as DrawingKind);
  };

  const cursorBtn = railBtn(ICONS.cursor, "Cursor");
  cursorBtn.onclick = () => { closeFlyout(); dm.setTool(null); };
  const groupBtns = new Map<string, HTMLElement>();
  for (const g of TOOL_GROUPS) {
    const b = railBtn(ICONS[g.title] ?? ICONS.cursor, g.title, true);
    groupBtns.set(g.title, b);
    b.onclick = () => openFlyout(b, (f) => {
      for (const s of g.sections) {
        f.append(el("div", "fly-head", s.header ?? g.title));
        for (const t of s.tools) f.append(item(t.title, t.placement, () => arm(t.kind), dm.tool() === t.kind));
      }
    });
  }
  const emojiBtn = railBtn(ICONS.emoji, "Emojis", true);
  groupBtns.set("emoji", emojiBtn);
  emojiBtn.onclick = () => openFlyout(emojiBtn, (f) => {
    f.append(el("div", "fly-head", "Emojis"));
    const grid = el("div", "emoji-grid");
    for (const e of EMOJIS) {
      const b = el("button", "", e);
      b.onclick = () => { closeFlyout(); dm.setTool("font-icon" as DrawingKind, { glyph: e }); };
      grid.append(b);
    }
    f.append(grid);
  });
  sep();

  // Magnet: the button toggles, the corner arrow picks weak / strong (TV).
  let magnetMode: Exclude<MagnetMode, "off"> = "weak";
  let magnetOn = false;
  const magnetBtn = railBtn(ICONS.magnet, "Magnet mode", true);
  const setMagnet = (on: boolean) => {
    magnetOn = on;
    dm.setMagnet(on ? magnetMode : "off");
    magnetBtn.classList.toggle("active", on);
    magnetBtn.title = `Magnet mode: ${on ? `${magnetMode} magnet` : "off"}`;
  };
  magnetBtn.onclick = (e) => {
    if ((e.target as HTMLElement).classList.contains("more")) {
      openFlyout(magnetBtn, (f) => {
        f.append(el("div", "fly-head", "Magnet"));
        f.append(item("Weak magnet", "snaps near OHLC", () => { magnetMode = "weak"; setMagnet(true); }, magnetOn && magnetMode === "weak"));
        f.append(item("Strong magnet", "always snaps to OHLC", () => { magnetMode = "strong"; setMagnet(true); }, magnetOn && magnetMode === "strong"));
      });
      return;
    }
    closeFlyout();
    setMagnet(!magnetOn);
  };
  const keepBtn = railBtn(ICONS.keep, "Keep drawing");
  let keep = false;
  keepBtn.onclick = () => {
    keep = !keep;
    dm.setStayInDrawingMode(keep);
    keepBtn.classList.toggle("active", keep);
  };
  // Hide all drawings (TV): the corner arrow lists the drawings hidden one by
  // one from the selection bar, to show them again.
  const eyeBtn = railBtn(ICONS.eye, "Hide all drawings", true);
  const eyeMore = eyeBtn.lastElementChild!;
  const refreshEye = () => {
    const on = dm.drawingsVisible();
    eyeBtn.firstElementChild!.outerHTML = on ? ICONS.eye : ICONS.eyeOff;
    eyeBtn.classList.toggle("active", !on);
    eyeBtn.title = on ? "Hide all drawings" : "Show all drawings";
  };
  eyeBtn.onclick = (e) => {
    if (e.target === eyeMore) {
      openFlyout(eyeBtn, (f) => {
        const hidden = dm.drawings().filter((d) => d.hidden);
        f.append(el("div", "fly-head", "Hidden drawings"));
        if (!hidden.length) f.append(item("No hidden drawing", "", () => {}));
        for (const d of hidden) f.append(item(TOOLS.get(d.kind)?.title ?? d.kind, "show", () => dm.setHidden(d.id, false)));
        if (hidden.length > 1) f.append(item("Show all", "", () => { for (const d of hidden) dm.setHidden(d.id, false); }));
      });
      return;
    }
    closeFlyout();
    dm.setDrawingsVisible(!dm.drawingsVisible());
  };
  watch("visibility", refreshEye);
  const trashBtn = railBtn(ICONS.trash, "Remove drawings", true);
  trashBtn.onclick = () => openFlyout(trashBtn, (f) => {
    const n = dm.drawings().length;
    f.append(item(n ? `Remove ${n} drawing${n === 1 ? "" : "s"}` : "No drawings to remove", "", () => { if (n) dm.clear(); }));
  });

  const refreshRail = () => {
    const k = dm.tool();
    const g = k ? TOOLS.get(k)?.group : undefined;
    cursorBtn.classList.toggle("active", !k);
    for (const [title, b] of groupBtns) {
      b.classList.toggle("active", title === g);
      if (title === g) b.title = `${title}: ${TOOLS.get(k!)!.title}`;
    }
  };
  watch("tool", () => { refreshRail(); refreshHint(); });
  refreshRail();
  refreshHint();

  // ---- image (Annotation tools / Content): the host reads the file and
  // puts it in the core image cache under a name; the drawing stores it.
  imageFile.onchange = async () => {
    const f = imageFile.files?.[0];
    if (!f) return;
    const url = await new Promise<string>((res) => { const r = new FileReader(); r.onload = () => res(String(r.result)); r.readAsDataURL(f); });
    const img = await decodeImage(url);
    if (disposed) return;
    if (!options.isEditable()) { flash("Chart is busy. Please choose the image again when loading finishes."); return; }
    const name = `${options.assetScope}:${Date.now().toString(36)}-${f.name}`;
    try { await options.saveImage(name, f); }
    catch { flash("Could not save this image to the browser. Image was not added."); return; }
    if (disposed) return;
    if (!options.isEditable()) { flash("Chart is busy. Please choose the image again when loading finishes."); return; }
    cacheImage(name, img);
    dm.addImage({ name, width: img.width, height: img.height });
    imageFile.value = "";
  };

  // ---- selection bar: tool name, Anchor drawing (Text, Pin, Table), delete
  const selbar = $("selbar");
  const refreshSelbar = () => {
    const ds = dm.selection().map((id) => dm.get(id)).filter((d): d is Drawing => !!d);
    selbar.hidden = ds.length === 0;
    if (!ds.length) return;
    selbar.replaceChildren();
    const one = ds.length === 1 ? ds[0] : undefined;
    selbar.append(el("span", "title", one ? TOOLS.get(one.kind)?.title ?? one.kind : `${ds.length} drawings`));
    if (one && isAnchorable(one.kind)) {
      const a = el("button", `tool${one.anchored ? " active" : ""}`, ICONS.anchor);
      a.title = one.anchored ? "Anchored: keeps its place on the pane (click to unanchor)" : "Anchor drawing: keep its place on the pane when the chart scrolls";
      a.onclick = () => dm.toggleAnchored(one.id);
      selbar.append(a);
    }
    const hide = el("button", "tool", ICONS.eyeOff);
    hide.title = "Hide (the eye button's menu shows it again)";
    hide.onclick = () => { for (const d of ds) dm.setHidden(d.id, true); };
    selbar.append(hide);
    const del = el("button", "tool", ICONS.trash);
    del.title = "Remove";
    del.onclick = () => { for (const d of ds) if (!d.locked) dm.remove(d.id); };
    selbar.append(del);
  };
  watch("selection", () => { refreshSelbar(); refreshHint(); });
  watch("update", refreshSelbar);
  watch("remove", refreshSelbar);

  // ---- inline editor for text tools and table cells
  const editor = $<HTMLTextAreaElement>("editor");
  let commit: ((text: string) => void) | null = null;
  let cancel: (() => void) | null = null;
  // The manager asks for the editor inside the mouse press: open it after
  // the release, else the release moves the focus away and closes it.
  let pressed = false;
  listen(window, "pointerdown", () => { pressed = true; }, true);
  listen(window, "pointerup", () => { pressed = false; }, true);
  const afterRelease = (fn: () => void) => {
    if (!pressed) return fn();
    listen(window, "pointerup", () => later(fn), { once: true });
  };
  const openEditor = (left: number, top: number, width: number, value: string, onCommit: (t: string) => void, onCancel: () => void) => {
    commit = (t) => { if (t !== value) onCommit(t); else onCancel(); };
    cancel = onCancel;
    const wrap = $("chartWrap").getBoundingClientRect();
    editor.style.left = `${Math.max(4, Math.min(left, wrap.width - 180))}px`;
    editor.style.top = `${Math.max(4, Math.min(top, wrap.height - 60))}px`;
    editor.style.width = `${Math.max(180, width)}px`;
    editor.value = value;
    editor.hidden = false;
    options.onEditorChange(true);
    editor.focus();
    editor.select();
  };
  const closeEditor = (ok: boolean) => {
    if (editor.hidden) return;
    editor.hidden = true;
    options.onEditorChange(false);
    const c = commit;
    const x = cancel;
    commit = cancel = null;
    if (ok) c?.(editor.value);
    else x?.();
  };
  listen(editor, "keydown", (e) => {
    e.stopPropagation();
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); closeEditor(true); }
    else if (e.key === "Escape") { e.preventDefault(); closeEditor(false); }
  });
  listen(editor, "blur", () => closeEditor(true));
  const autoText = (): string | undefined => undefined;

  watch("textEdit", (d, p) => {
    const setText = (text: string) => { const cur = dm.get(d.id); if (cur && cur.text !== text) dm.update({ ...cur, text }); };
    const auto = autoText();
    if (auto != null) return setText(auto);
    afterRelease(() => openEditor(p.x + 8, p.y - 16, 0, d.text ?? "", setText, () => {}));
  });
  watch("tableEdit", (d, cell, box) => {
    const auto = autoText();
    if (auto != null) { dm.setTableCellText(d.id, cell, auto); dm.endTableEdit(); return; }
    const cells = (d.style as { tableCells?: string[][] }).tableCells;
    afterRelease(() => openEditor(box.left, box.top, box.width, cells?.[cell[0]]?.[cell[1]] ?? "", (t) => { dm.setTableCellText(d.id, cell, t); dm.endTableEdit(); }, () => dm.endTableEdit()));
  });

 return ()=>{options.onEditorChange(false);disposed=true;for(const off of cleanup)off();for(const timer of timers)clearTimeout(timer);root.replaceChildren();};
}
